<?php require __DIR__.'/inc/header.php';$title='Sitemap Importer';$pdo=db();$msg='';if(is_post()){verify_csrf();$url=trim((string)post('url'));$type=(string)post('post_type','articles');$imported=$skipped=$errors=0;$logs=[];if($url && filter_var($url,FILTER_VALIDATE_URL)){$xml=@file_get_contents($url);if($xml===false && function_exists('curl_init')){$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_TIMEOUT=>20]);$xml=curl_exec($ch);curl_close($ch);}if($xml){$sx=@simplexml_load_string($xml);if($sx){$urls=[];foreach($sx->url as $u)$urls[]=(string)$u->loc;foreach($sx->sitemap as $sm){$sub=(string)$sm->loc;$x=@file_get_contents($sub);if($x){$ss=@simplexml_load_string($x);if($ss)foreach($ss->url as $u)$urls[]=(string)$u->loc;}}foreach(array_slice(array_unique($urls),0,100) as $u){$slug=slugify(basename(parse_url($u,PHP_URL_PATH)?:'imported'));$st=$pdo->prepare('SELECT id FROM content_posts WHERE post_type=? AND slug=?');$st->execute([$type,$slug]);if($st->fetch()){++$skipped;continue;}$html=@file_get_contents($u);if(!$html){++$errors;continue;}$dom=new DOMDocument();@$dom->loadHTML($html);$titleNode=$dom->getElementsByTagName('title')->item(0);$t=$titleNode?trim($titleNode->textContent):ucwords(str_replace('-',' ',$slug));$st=$pdo->prepare('INSERT OR IGNORE INTO content_posts(post_type,title,slug,excerpt,content,status,author_id,published_at) VALUES(?,?,?,?,?,?,?,?)');$st->execute([$type,$t,$slug,'Imported from '.$u,'<p>Imported source: '.htmlspecialchars($u,ENT_QUOTES).'</p>','draft',user()['id']??null,null]);$imported++;}$logs[]='Imported URLs from '.$url;}else $errors++;}else $errors++;}else $errors++;$pdo->prepare('INSERT INTO import_runs(source,source_type,imported,skipped,errors,logs) VALUES(?,?,?,?,?,?)')->execute([$url,'sitemap',$imported,$skipped,$errors,implode("\n",$logs)]);flash('success',"Importer finished: $imported imported, $skipped skipped, $errors errors.");redirect('/admin/importer.php');}$runs=$pdo->query('SELECT * FROM import_runs ORDER BY id DESC LIMIT 10')->fetchAll();?><div class="grid xl:grid-cols-[430px_1fr] gap-6"><div class="bg-white border rounded-2xl p-5 soft"><div class="font-black text-lg">Import from WordPress / Sitemap</div><p class="text-sm text-slate-500 mt-2">Paste a sitemap XML URL such as <code>/sitemap_index.xml</code>. Imported posts start as drafts so you can review content before publishing.</p><form method="post" class="mt-4 space-y-3"><?=csrf_input()?><input name="url" required type="url" placeholder="https://example.com/sitemap_index.xml" class="w-full rounded-xl border-slate-200"><select name="post_type" class="w-full rounded-xl border-slate-200"><?php foreach(['gadgets','jersey','fashion','articles','docs','pages'] as $t):?><option><?=$t?></option><?php endforeach;?></select><button class="shine grad600 text-white w-full py-3 rounded-xl font-black">Import Sitemap</button></form></div><div class="bg-white border rounded-2xl p-5 soft"><div class="font-black">Import History</div><div class="space-y-3 mt-4"><?php foreach($runs as $r):?><div class="rounded-xl bg-slate-50 p-3"><div class="font-bold text-sm truncate"><?=e($r['source'])?></div><div class="text-xs text-slate-400 mt-1"><?=$r['imported']?> imported · <?=$r['skipped']?> skipped · <?=$r['errors']?> errors</div></div><?php endforeach;?></div></div></div><?php require __DIR__.'/inc/footer.php'; ?>
